#include <stdint.h>
#include <string.h>

static uint32_t ftz_u32(uint32_t bits) {
    uint32_t exp = (bits >> 23) & 0xFF;
    uint32_t exp_is_zero = (exp - 1) >> 31;
    uint32_t mask = 0xFFFFFFFF ^ (exp_is_zero * 0x7FFFFFFF);
    return bits & mask;
}

static float ftz_f32(float x) {
    uint32_t bits;
    memcpy(&bits, &x, 4);
    bits = ftz_u32(bits);
    memcpy(&x, &bits, 4);
    return x;
}

static uint32_t canon_nan(float x) {
    uint32_t bits;
    memcpy(&bits, &x, 4);
    uint32_t exp = (bits >> 23) & 0xFF;
    uint32_t frac = bits & 0x7FFFFF;
    uint32_t is_nan = (exp == 0xFF) & (frac != 0);
    uint32_t m = (uint32_t)0 - is_nan;
    return (0x7FC00000 & m) | (bits & ~m);
}

void fmac_custom_model(const uint32_t in[3], uint32_t out[3]) {
    float a, b, c;
    uint32_t tmp;

    tmp = ftz_u32(in[0]); memcpy(&a, &tmp, 4);
    tmp = ftz_u32(in[1]); memcpy(&b, &tmp, 4);
    tmp = ftz_u32(in[2]); memcpy(&c, &tmp, 4);

    float p = ftz_f32(a * b);
    uint32_t p_bits = canon_nan(p);
    memcpy(&p, &p_bits, 4);

    float s = ftz_f32(c + p);
    uint32_t s_bits = canon_nan(s);

    out[0] = ftz_u32(s_bits);
    out[1] = 0;
    out[2] = 0;
}

instructions.spike_model:
namespace {
    inline uint32_t float_to_bits(float f) {
        uint32_t b;
        std::memcpy(&b, &f, 4);
        return b;
    }

    inline float bits_to_float(uint32_t b) {
        float f;
        std::memcpy(&f, &b, 4);
        return f;
    }

    inline uint32_t nz_mask(uint32_t x) {
        uint32_t sign = (x | (0u - x)) >> 31;
        return 0u - sign;
    }

    inline uint32_t z_mask(uint32_t x) {
        return ~nz_mask(x);
    }

    inline uint32_t ftz_bits(uint32_t bits) {
        uint32_t exp = (bits >> 23) & 0xFF;
        uint32_t m = z_mask(exp);
        return (bits & ~m) | ((bits & 0x80000000) & m);
    }

    inline uint32_t canon_nan_bits(uint32_t bits) {
        uint32_t exp = (bits >> 23) & 0xFF;
        uint32_t frac = bits & 0x7FFFFF;
        uint32_t is_ff_exp_mask = z_mask(exp ^ 0xFF);
        uint32_t is_frac_nz_mask = nz_mask(frac);
        uint32_t m = is_ff_exp_mask & is_frac_nz_mask;
        return (0x7FC00000 & m) | (bits & ~m);
    }
}

void fmac_custom_iss(const uint32_t in[3], uint32_t out[3]) {
    uint32_t a_bits = ftz_bits(in[0]);
    uint32_t b_bits = ftz_bits(in[1]);
    uint32_t c_bits = ftz_bits(in[2]);

    float a = bits_to_float(a_bits);
    float b = bits_to_float(b_bits);
    float c = bits_to_float(c_bits);

    float p_f = a * b;
    uint32_t p_bits = float_to_bits(p_f);
    p_bits = ftz_bits(p_bits);
    p_bits = canon_nan_bits(p_bits);

    float p = bits_to_float(p_bits);
    float res_f = c + p;
    uint32_t res_bits = float_to_bits(res_f);
    res_bits = ftz_bits(res_bits);
    res_bits = canon_nan_bits(res_bits);

    out[0] = res_bits;
    out[1] = 0;
    out[2] = 0;
}
